document.addEventListener('DOMContentLoaded',()=>{const results=document.getElementById('servicios');if(!results)return;const form=document.querySelector('[data-complete-quote],[data-public-quote]');if(!form)return;const contractual='[data-postal-display],[data-postal],[data-settlement],input[name="origin_address"],input[name="destination_address"],input[name="sender[street]"],input[name="sender[exterior]"],input[name="recipient[street]"],input[name="recipient[exterior]"],[data-package-type],[data-weight],[data-dimension]';let current=true;const invalidate=event=>{if(!current||!event.target.matches(contractual))return;current=false;results.querySelectorAll('button,input').forEach(control=>control.disabled=true);results.remove()};form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);requestAnimationFrame(()=>results.scrollIntoView({behavior:'smooth',block:'start'}))});
